package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
)

const shardingReportSchemaVersion = "eventq.sharding-report/v1"
const shardingReportDigestSchemaVersion = "eventq.sharding-report-digest/v1"
const shardingReportHistogramSchemaVersion = "eventq.sharding-report-histogram/v1"

type shardingReportShard struct {
	Shard                      string  `json:"shard"`
	Bytes                      int64   `json:"bytes"`
	SHA256                     string  `json:"sha256"`
	EventsTotal                int     `json:"events_total"`
	EventsAccepted             int     `json:"events_accepted"`
	EventsInvalid              int     `json:"events_invalid"`
	EventsLate                 int     `json:"events_late"`
	EventsDuplicate            int     `json:"events_duplicate"`
	EventsUnresolvedChargeback int     `json:"events_unresolved_chargeback"`
	FirstTS                    *string `json:"first_ts"`
	LastTS                     *string `json:"last_ts"`
}

type shardingReportTotals struct {
	Shards                      int   `json:"shards"`
	BytesTotal                  int64 `json:"bytes_total"`
	EventsTotal                  int   `json:"events_total"`
	EventsAccepted              int   `json:"events_accepted"`
	EventsInvalid                int   `json:"events_invalid"`
	EventsLate                   int   `json:"events_late"`
	EventsDuplicate              int   `json:"events_duplicate"`
	EventsUnresolvedChargeback  int   `json:"events_unresolved_chargeback"`
}

type shardingReport struct {
	SchemaVersion string                  `json:"schema_version"`
	IngestID      *string                 `json:"ingest_id"`
	Shards        []shardingReportShard   `json:"shards"`
	Totals        shardingReportTotals    `json:"totals"`
}

type shardingReportDigest struct {
	SchemaVersion       string `json:"schema_version"`
	ReportPath          string `json:"report_path"`
	ReportSHA256        string `json:"report_sha256"`
	ReportBytes         int64  `json:"report_bytes"`
	ShardCount          int    `json:"shard_count"`
	SortKey             string `json:"sort_key,omitempty"`
	ShardsSortedInvariant *bool `json:"shards_sorted_invariant,omitempty"`
	ToolVersion         string `json:"tool_version"`
}

type shardingReportIndexEntry struct {
	Name string `json:"name"`
	Type string `json:"type"`
	Path string `json:"path"`
}

type shardingReportIndex struct {
	Entries       []shardingReportIndexEntry `json:"entries"`
	EntryCount    int                        `json:"entry_count"`
	ShardCount    int                        `json:"shard_count"`
	GeneratedFrom string                     `json:"generated_from"`
	ToolVersion   string                     `json:"tool_version"`
}

type shardingReportHistogramBucket struct {
	UpperBound int `json:"upper_bound"`
	Count      int `json:"count"`
}

type shardingReportHistogram struct {
	SchemaVersion string                            `json:"schema_version"`
	ReportPath    string                            `json:"report_path"`
	ShardCount    int                              `json:"shard_count"`
	Buckets       map[string][]shardingReportHistogramBucket `json:"buckets"`
	ToolVersion   string                            `json:"tool_version"`
}

func writeShardingReportSidecars(cfg cliConfig, shards []inputShardInfo, auditEntries []auditLogEntry, events []rawEvent) error {
	if cfg.shardingReport == "" {
		return nil
	}
	reportShards := buildShardingReportShards(cfg, shards, auditEntries, events)
	sortKey := cfg.shardingReportSort
	if sortKey == "" {
		sortKey = "basename"
	}
	sortShardingReportShards(reportShards, sortKey)

	var ingestID *string
	if cfg.ingestIDSet {
		id := cfg.ingestID
		ingestID = &id
	}
	totals := shardingReportTotals{Shards: len(reportShards)}
	for _, s := range reportShards {
		totals.BytesTotal += s.Bytes
		totals.EventsTotal += s.EventsTotal
		totals.EventsAccepted += s.EventsAccepted
		totals.EventsInvalid += s.EventsInvalid
		totals.EventsLate += s.EventsLate
		totals.EventsDuplicate += s.EventsDuplicate
		totals.EventsUnresolvedChargeback += s.EventsUnresolvedChargeback
	}
	report := shardingReport{
		SchemaVersion: shardingReportSchemaVersion,
		IngestID:      ingestID,
		Shards:        reportShards,
		Totals:        totals,
	}
	data, err := json.MarshalIndent(report, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	if err := atomicWriteFile(cfg.shardingReport, data); err != nil {
		return err
	}

	reportBase := filepath.Base(cfg.shardingReport)
	if cfg.shardingReportHistogram != "" {
		if err := writeShardingHistogram(cfg.shardingReportHistogram, reportBase, reportShards, totals.Shards); err != nil {
			return err
		}
	}
	if cfg.shardingReportDigest != "" {
		if err := writeShardingDigest(cfg, data, reportBase, totals.Shards, sortKey, reportShards); err != nil {
			return err
		}
	}
	if cfg.shardingReportIndex != "" {
		if err := writeShardingIndex(cfg.shardingReportIndex, reportBase, reportShards); err != nil {
			return err
		}
	}
	return nil
}

func buildShardingReportShards(cfg cliConfig, shards []inputShardInfo, auditEntries []auditLogEntry, events []rawEvent) []shardingReportShard {
	counts := map[string]map[string]int{}
	for _, e := range auditEntries {
		if counts[e.Shard] == nil {
			counts[e.Shard] = map[string]int{}
		}
		counts[e.Shard][e.Bucket]++
	}
	tsRanges := map[string]*shardTSRange{}
	for _, raw := range events {
		if raw.Invalid || raw.Blank || raw.Obj == nil {
			continue
		}
		ts, ok, _ := getRawString(raw.Obj, "ts")
		if !ok || !isExactRFC3339UTC(ts) {
			continue
		}
		r := tsRanges[raw.Shard]
		if r == nil {
			r = &shardTSRange{}
			tsRanges[raw.Shard] = r
		}
		if r.first == "" || ts < r.first {
			r.first = ts
		}
		if r.last == "" || ts > r.last {
			r.last = ts
		}
	}
	out := make([]shardingReportShard, 0, len(shards))
	for _, s := range shards {
		c := counts[s.Name]
		r := tsRanges[s.Name]
		rec := shardingReportShard{
			Shard:                      s.Name,
			Bytes:                      s.Bytes,
			SHA256:                     s.SHA256,
			EventsTotal:                s.EventsTotal,
			EventsAccepted:             c["accepted"],
			EventsInvalid:              c["invalid"],
			EventsLate:                  c["late"],
			EventsDuplicate:            c["duplicate"],
			EventsUnresolvedChargeback: c["unresolved_chargeback"],
		}
		if r != nil && r.first != "" {
			first := r.first
			last := r.last
			rec.FirstTS = &first
			rec.LastTS = &last
		}
		out = append(out, rec)
	}
	return out
}

type shardTSRange struct {
	first string
	last  string
}

func isExactRFC3339UTC(s string) bool {
	if len(s) != 20 {
		return false
	}
	if s[19] != 'Z' {
		return false
	}
	for _, p := range [][2]int{{0, 4}, {5, 7}, {8, 10}, {11, 13}, {14, 16}, {17, 19}} {
		for i := p[0]; i < p[1]; i++ {
			if s[i] < '0' || s[i] > '9' {
				return false
			}
		}
	}
	return s[4] == '-' && s[7] == '-' && s[10] == 'T' && s[13] == ':' && s[16] == ':'
}

func sortShardingReportShards(shards []shardingReportShard, sortKey string) {
	switch sortKey {
	case "bytes":
		sort.SliceStable(shards, func(i, j int) bool {
			if shards[i].Bytes != shards[j].Bytes {
				return shards[i].Bytes < shards[j].Bytes
			}
			return shards[i].Shard < shards[j].Shard
		})
	case "sha256":
		sort.SliceStable(shards, func(i, j int) bool {
			if shards[i].SHA256 != shards[j].SHA256 {
				return shards[i].SHA256 < shards[j].SHA256
			}
			return shards[i].Shard < shards[j].Shard
		})
	default:
		sort.SliceStable(shards, func(i, j int) bool {
			return shards[i].Shard < shards[j].Shard
		})
	}
}

func writeShardingDigest(cfg cliConfig, reportData []byte, reportBase string, shardCount int, sortKey string, reportShards []shardingReportShard) error {
	h, b, err := fileDigest(cfg.shardingReport)
	if err != nil {
		return err
	}
	digest := shardingReportDigest{
		SchemaVersion: shardingReportDigestSchemaVersion,
		ReportPath:    reportBase,
		ReportSHA256:  h,
		ReportBytes:   b,
		ShardCount:    shardCount,
		ToolVersion:   toolVersion,
	}
	if cfg.shardingReportStrict {
		invariant := shardsSortedInvariant(reportShards, sortKey)
		digest.SortKey = sortKey
		digest.ShardsSortedInvariant = &invariant
	}
	data, err := json.MarshalIndent(digest, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	return atomicWriteFile(cfg.shardingReportDigest, data)
}

func shardsSortedInvariant(shards []shardingReportShard, sortKey string) bool {
	clone := append([]shardingReportShard(nil), shards...)
	sortShardingReportShards(clone, sortKey)
	if len(clone) != len(shards) {
		return false
	}
	for i := range clone {
		if clone[i] != shards[i] {
			return false
		}
	}
	return true
}

func writeShardingIndex(path, reportBase string, reportShards []shardingReportShard) error {
	entries := make([]shardingReportIndexEntry, 0, len(reportShards)*11)
	for i, s := range reportShards {
		entries = appendShardIndexEntries(entries, i, s)
	}
	idx := shardingReportIndex{
		Entries:       entries,
		EntryCount:    len(entries),
		ShardCount:    len(reportShards),
		GeneratedFrom: reportBase,
		ToolVersion:   toolVersion,
	}
	data, err := json.MarshalIndent(idx, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	return atomicWriteFile(path, data)
}

func appendShardIndexEntries(entries []shardingReportIndexEntry, i int, s shardingReportShard) []shardingReportIndexEntry {
	fields := []struct {
		name string
		val  any
	}{
		{"shard", s.Shard},
		{"bytes", s.Bytes},
		{"sha256", s.SHA256},
		{"events_total", s.EventsTotal},
		{"events_accepted", s.EventsAccepted},
		{"events_invalid", s.EventsInvalid},
		{"events_late", s.EventsLate},
		{"events_duplicate", s.EventsDuplicate},
		{"events_unresolved_chargeback", s.EventsUnresolvedChargeback},
		{"first_ts", s.FirstTS},
		{"last_ts", s.LastTS},
	}
	for _, f := range fields {
		entries = append(entries, shardingReportIndexEntry{
			Name: f.name,
			Type: indexType(f.val),
			Path: fmt.Sprintf("$.shards[%d].%s", i, f.name),
		})
	}
	return entries
}

func indexType(v any) string {
	switch v.(type) {
	case string:
		return "string"
	case int, int64:
		return "integer"
	case *string:
		if v.(*string) == nil {
			return "null"
		}
		return "string"
	default:
		return "null"
	}
}

func writeShardingHistogram(path, reportBase string, reportShards []shardingReportShard, shardCount int) error {
	buckets := map[string][]shardingReportHistogramBucket{}
	for _, m := range shardingHistogramMetrics {
		values := make([]int, 0, len(reportShards))
		for _, s := range reportShards {
			values = append(values, shardingMetricValue(s, m))
		}
		buckets[m] = buildHistogram(values, shardCount)
	}
	hist := shardingReportHistogram{
		SchemaVersion: shardingReportHistogramSchemaVersion,
		ReportPath:    reportBase,
		ShardCount:    shardCount,
		Buckets:       buckets,
		ToolVersion:   toolVersion,
	}
	data, err := json.MarshalIndent(hist, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	return atomicWriteFile(path, data)
}

var shardingHistogramMetrics = []string{"bytes", "events_total", "events_accepted", "events_invalid", "events_late", "events_duplicate", "events_unresolved_chargeback"}

func shardingMetricValue(s shardingReportShard, metric string) int {
	switch metric {
	case "bytes":
		return int(s.Bytes)
	case "events_total":
		return s.EventsTotal
	case "events_accepted":
		return s.EventsAccepted
	case "events_invalid":
		return s.EventsInvalid
	case "events_late":
		return s.EventsLate
	case "events_duplicate":
		return s.EventsDuplicate
	case "events_unresolved_chargeback":
		return s.EventsUnresolvedChargeback
	default:
		return 0
	}
}

func buildHistogram(values []int, shardCount int) []shardingReportHistogramBucket {
	if shardCount == 0 {
		return []shardingReportHistogramBucket{}
	}
	vmax := 0
	zeroCount := 0
	for _, v := range values {
		if v > vmax {
			vmax = v
		}
		if v == 0 {
			zeroCount++
		}
	}
	if vmax == 0 {
		return []shardingReportHistogramBucket{{UpperBound: 0, Count: len(values)}}
	}
	var buckets []shardingReportHistogramBucket
	if zeroCount > 0 {
		buckets = append(buckets, shardingReportHistogramBucket{UpperBound: 0, Count: zeroCount})
	}
	prev := 0
	u := 1
	for u < vmax {
		u *= 2
	}
	for cur := 1; cur <= u; cur *= 2 {
		count := 0
		for _, v := range values {
			if v > prev && v <= cur {
				count++
			}
		}
		buckets = append(buckets, shardingReportHistogramBucket{UpperBound: cur, Count: count})
		prev = cur
	}
	return buckets
}

func validateShardingReportFlags(cfg *cliConfig) error {
	if cfg.shardingReport == "" {
		if cfg.shardingReportDigest != "" || cfg.shardingReportIndex != "" || cfg.shardingReportHistogram != "" || cfg.shardingReportSort != "" || cfg.shardingReportStrict {
			if cfg.shardingReportDigest != "" {
				return fmt.Errorf("ingest: --sharding-report-digest requires --sharding-report")
			}
			if cfg.shardingReportIndex != "" {
				return fmt.Errorf("ingest: --sharding-report-index requires --sharding-report and --sharding-report-digest")
			}
			if cfg.shardingReportHistogram != "" {
				return fmt.Errorf("ingest: --sharding-report-histogram requires --sharding-report")
			}
			if cfg.shardingReportSort != "" {
				return fmt.Errorf("ingest: --sharding-report-sort requires --sharding-report")
			}
			return fmt.Errorf("ingest: --sharding-report-strict requires --sharding-report")
		}
		return nil
	}
	if cfg.shardingReportDigest == "" && cfg.shardingReportIndex != "" {
		return fmt.Errorf("ingest: --sharding-report-index requires --sharding-report and --sharding-report-digest")
	}
	if cfg.shardingReportSort != "" && cfg.shardingReportSort != "basename" && cfg.shardingReportSort != "bytes" && cfg.shardingReportSort != "sha256" {
		return fmt.Errorf("ingest: --sharding-report-sort: value must be one of basename|bytes|sha256")
	}
	if cfg.shardingReport != "" && !parentDirExists(cfg.shardingReport) {
		return fmt.Errorf("ingest --sharding-report parent directory does not exist")
	}
	if cfg.shardingReportDigest != "" && !parentDirExists(cfg.shardingReportDigest) {
		return fmt.Errorf("ingest --sharding-report-digest parent directory does not exist")
	}
	if cfg.shardingReportIndex != "" && !parentDirExists(cfg.shardingReportIndex) {
		return fmt.Errorf("ingest --sharding-report-index parent directory does not exist")
	}
	if cfg.shardingReportHistogram != "" && !parentDirExists(cfg.shardingReportHistogram) {
		return fmt.Errorf("ingest --sharding-report-histogram parent directory does not exist")
	}
	return nil
}
